  [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3::after { margin-left: 5px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):last-of-type [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]), [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) { left: auto; right: -60px; min-width: 220px; }
}
@media (max-width: 400px) {
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"], [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"] :is(.media-html, .custom-html-block, iframe) { width: 34px !important; height: 34px !important; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) .canvas-button { font-size: 15px; padding: 6px 2px; }
