/* reGELerate Daylight style, shared by every page. Colours: ground #F4F1FC, ink #121014, muted #4D4766, violet #5B2FE0, line #D5CAF5, orange #FF8A1F.
   How it works for editors: text blocks are plain text, line breaks show as typed. Text blocks inside a frame become white cards. Set a card's padding to 26 and its first line shows as a small violet label.
   Buttons inside a frame become big black link buttons (first line is the title, second line the description). Buttons on their own are black pills.
   Give a text block a dark background and white text colour in the builder to make it a dark card. */
main { background: #F4F1FC; min-height: 100vh; overflow-x: clip; }
.page-canvas { max-width: 1296px; margin: 0 auto !important; padding: 0 28px 0 !important; box-sizing: border-box; }
.page-canvas > .canvas-section { align-self: start; }
.canvas-section:not([data-layer-kind="html"]) { height: auto !important; }
.canvas-section { font-family: "Sora", system-ui, -apple-system, "Segoe UI", sans-serif; color: #121014; min-width: 0; }
.media-block { padding-top: 0 !important; padding-bottom: 0 !important; }
.media-button { display: none !important; }
.canvas-section > .media-section { display: none !important; }
[data-layer-kind="html"] h2 { display: none !important; }
.media-text h2, .media-text h3 { font-family: "Sora", system-ui, -apple-system, "Segoe UI", sans-serif; letter-spacing: -.025em; text-wrap: balance; color: #121014; }
.media-text h2 { font-weight: 800; font-size: clamp(28px, 4.4vw, 44px); line-height: 1.08; margin: 0 0 12px; }
.media-text h3 { font-weight: 700; font-size: 20px; line-height: 1.25; margin: 0 0 8px; text-wrap: pretty; hyphens: none; }
.custom-text { white-space: pre-line; font-size: 17px; line-height: 1.6; color: #4D4766; overflow-wrap: break-word; max-width: 75ch; }
/* new pages: blocks live inside the page's content container */
[data-layer-id="custom-heading"] { display: none !important; }
[data-layer-id="custom-content"] { padding: 0 !important; display: block !important; }
[data-layer-id="custom-content"] > .canvas-children { display: block !important; }
[data-layer-id="custom-content"] > .canvas-children > .canvas-section:not(:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"])) { width: auto !important; translate: none !important; }
/* spacing between blocks */
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"] { margin-top: 20px; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:has(> .media-text > h2) { margin-top: 64px; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="section"] { padding: 8px !important; margin-top: 4px; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="html"] { margin-top: 12px; }
/* dark blocks: background and text colour come from the builder settings */
.canvas-section[style*="--node-color"] { border-radius: 20px; }
.canvas-section[style*="--node-color"] :is(h2, h3, .custom-text) { color: var(--node-color) !important; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > .canvas-section[style*="--node-color"] { padding: 40px !important; margin-inline: 8px; }
/* frames lay their blocks out on their own grid */
[data-layer-kind="section"] > .canvas-children > .canvas-section { grid-column: auto !important; margin: 0 !important; }
[data-layer-kind="section"] > .canvas-children:has(> [data-layer-kind="text"]) { display: grid !important; grid-template-columns: repeat(auto-fit, minmax(min(100%, 285px), 1fr)); gap: 14px !important; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="text"] { background: #FFFFFF; border-radius: 20px; padding: 26px !important; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="text"] .custom-text { font-size: 16px; }
/* a card whose padding is set to 26 in the builder shows its first line as a small violet label */
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="text"]:is([style*="padding-inline: 26px"],[style*="padding-inline:26px"]) .custom-text::first-line { font-size: 12.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: #5B2FE0; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="text"]:is([style*="padding-inline: 26px"],[style*="padding-inline:26px"])[style*="--node-color"] .custom-text::first-line { color: #B9A6FF; }
/* buttons */
.canvas-button > span + span { display: none !important; }
.canvas-button { font-family: "Sora", system-ui, -apple-system, "Segoe UI", sans-serif; display: inline-block; margin: 0 !important; background: #121014 !important; color: #FFFFFF !important; text-decoration: none; font-weight: 700; font-size: 15px; line-height: 1.2; padding: 13px 22px; border: 0; border-radius: 999px; }
.canvas-button:hover { background: #5B2FE0 !important; }
[data-layer-kind="section"] > .canvas-children:has(> [data-layer-kind="button"]) { display: grid !important; grid-template-columns: repeat(auto-fill, minmax(min(100%, 320px), 1fr)); grid-auto-rows: 1fr; gap: 12px !important; align-items: stretch; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="button"] { padding: 0 !important; display: grid; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="button"] .canvas-button { position: relative; display: block; box-sizing: border-box; width: 100%; height: 100%; min-height: 96px; white-space: pre-line; text-align: left; color: #C9C4D6 !important; border-radius: 20px; padding: 17px 70px 17px 20px; font-size: 13.5px; font-weight: 400; line-height: 1.45; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="button"] .canvas-button::first-line { color: #FFFFFF; font-size: 17px; font-weight: 700; }
[data-layer-kind="section"] > .canvas-children > [data-layer-kind="button"] .canvas-button::after { content: "→"; position: absolute; right: 18px; top: 50%; margin-top: -19px; width: 38px; height: 38px; border-radius: 50%; background: #FFFFFF; color: #121014; display: grid; place-items: center; font-size: 17px; font-weight: 800; }
/* the page title is the built-in intro block */
[data-layer-id="custom-intro"] { margin-top: 0 !important; padding-top: 64px !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) + * { margin-top: 0 !important; }
[data-layer-id="custom-intro"] h2 { font-size: clamp(40px, 6.4vw, 76px) !important; line-height: 1 !important; margin-bottom: 18px !important; }
[data-layer-id="custom-intro"] .custom-text { font-size: 19px; }
/* the last block, when dark, is the contact footer */
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:last-child[style*="--node-color"] { border-radius: 20px 20px 0 0; margin-top: 72px !important; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:last-child[style*="--node-color"] h2 { font-size: 22px; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:last-child[style*="--node-color"] .custom-text { font-size: 14.5px; }
:is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="button"] { margin-top: 16px; }
/* collapsible sections: one per person, the body keeps its typed line breaks */
.media-accordion { font-family: "Sora", system-ui, -apple-system, "Segoe UI", sans-serif; }
.accordion-item { border-bottom: 1px solid #D5CAF5; }
.accordion-item > summary { font-weight: 700; font-size: 17px; padding: 14px 2px; cursor: pointer; }
.accordion-body { white-space: pre-line; font-size: 16px; line-height: 1.6; color: #4D4766; padding: 0 2px 18px; max-width: 75ch; }
/* site header: logo, home link, Project and Engagement menus, Team link.
   It is the frame whose padding is 3; its menus have padding 4; each menu's list of links has padding 5. */
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) { position: sticky !important; top: 0; z-index: 60; width: 100vw !important; margin: 0 0 0 calc(50% - 50vw) !important; padding: 0 !important; background: rgba(255, 255, 255, .9); -webkit-backdrop-filter: saturate(1.6) blur(14px); backdrop-filter: saturate(1.6) blur(14px); border-bottom: 1px solid #E2D9F7; border-radius: 0; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children { display: flex !important; align-items: center; gap: 2px !important; max-width: 1296px; margin: 0 auto; padding: 9px 28px; box-sizing: border-box; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > .canvas-section { padding: 0 !important; margin: 0 !important; width: auto !important; flex: none; background: none !important; border-radius: 0 !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"] { width: 40px !important; height: 40px !important; min-height: 0 !important; margin-right: 6px !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"] :is(.media-html, .custom-html-block, iframe) { width: 40px !important; height: 40px !important; min-height: 0 !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button { background: transparent !important; color: #121014 !important; font-size: 14.5px; font-weight: 600; padding: 9px 13px; min-height: 0; width: auto; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button:hover { background: #F4F1FC !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button::first-line { color: inherit; font-size: inherit; font-weight: inherit; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button::after { content: none; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) { margin-right: auto !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) .canvas-button { font-size: 21px; font-weight: 800; letter-spacing: -.03em; padding: 6px 4px; }
[data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) .canvas-button:hover { background: transparent !important; color: #5B2FE0 !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) { position: relative; cursor: pointer; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children { display: block !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] { background: transparent !important; padding: 0 !important; border-radius: 999px; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3 { font-size: 14.5px !important; font-weight: 600 !important; letter-spacing: 0; margin: 0 !important; padding: 9px 13px; border-radius: 999px; white-space: nowrap; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3::after { content: ""; display: inline-block; width: 6px; height: 6px; margin-left: 8px; border-right: 2px solid currentColor; border-bottom: 2px solid currentColor; transform: rotate(45deg) translateY(-3px); }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] .custom-text { display: none; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):hover > .canvas-children > [data-layer-kind="text"] h3, [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):focus-within > .canvas-children > [data-layer-kind="text"] h3 { background: #F4F1FC; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) { display: none; position: absolute !important; top: 100%; left: 0; min-width: 250px; padding: 8px !important; margin: 0 !important; background: #FFFFFF; border-radius: 14px; box-shadow: 0 0 0 1.5px #D5CAF5, 0 14px 30px rgba(18, 16, 20, .12); z-index: 70; }
[data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):hover > .canvas-children > [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]), [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):focus-within > .canvas-children > [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) { display: block; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) > .canvas-children { display: grid !important; grid-template-columns: minmax(0, 1fr) !important; gap: 2px !important; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button { display: block; width: 100%; min-height: 0; background: transparent !important; color: #121014 !important; text-align: left; font-size: 14.5px; font-weight: 600; padding: 9px 12px; border-radius: 8px; white-space: normal; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button::first-line { color: inherit; font-size: inherit; font-weight: inherit; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button::after { content: none; }
[data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button:hover { background: #F4F1FC !important; }
@media (max-width: 600px) {
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children { padding: 7px 14px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"] { margin-right: 2px !important; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) .canvas-button { font-size: 17px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button, [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3 { font-size: 13px !important; padding: 8px 7px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3::after { margin-left: 5px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]):last-of-type [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]), [data-layer-kind="section"]:is([style*="padding-inline: 5px"],[style*="padding-inline:5px"]) { left: auto; right: -60px; min-width: 220px; }
}
@media (max-width: 400px) {
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"], [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="html"] :is(.media-html, .custom-html-block, iframe) { width: 34px !important; height: 34px !important; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"]:nth-child(2) .canvas-button { font-size: 15px; padding: 6px 2px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 3px"],[style*="padding-inline:3px"]) > .canvas-children > [data-layer-kind="button"] .canvas-button, [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3 { font-size: 12px !important; padding: 8px 4px; }
  [data-layer-kind="section"]:is([style*="padding-inline: 4px"],[style*="padding-inline:4px"]) > .canvas-children > [data-layer-kind="text"] h3::after { margin-left: 4px; width: 5px; height: 5px; }
}
/* desktop: a section heading and its lead paragraph sit side by side */
@media (min-width: 1080px) {
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:not([data-layer-id="custom-intro"]):not([style*="--node-color"]):has(> .media-text > h2):has(> .media-text > .custom-text:not(:empty)) > .media-text { display: grid; grid-template-columns: minmax(0, 6fr) minmax(0, 6fr); column-gap: 56px; align-items: end; }
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:not([data-layer-id="custom-intro"]):not([style*="--node-color"]):has(> .media-text > h2):has(> .media-text > .custom-text:not(:empty)) > .media-text > h2 { grid-column: 1; grid-row: 1; margin-bottom: 0; }
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:not([data-layer-id="custom-intro"]):not([style*="--node-color"]):has(> .media-text > h2):has(> .media-text > .custom-text:not(:empty)) > .media-text > .custom-text { grid-column: 2; grid-row: 1; max-width: 52ch; padding-bottom: 4px; }
  [data-layer-id="custom-intro"] .custom-text { max-width: 56ch; }
}
/* phones */
@media (max-width: 760px) {
  .page-canvas { padding: 0 14px 0 !important; }
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > .canvas-section { grid-column: 1 / -1 !important; }
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > [data-layer-kind="text"]:has(> .media-text > h2) { margin-top: 44px; }
  [data-layer-id="custom-intro"] { padding-top: 34px !important; }
  :is(.page-canvas, [data-layer-id="custom-content"] > .canvas-children) > .canvas-section[style*="--node-color"] { padding: 28px 22px !important; }
}
